import json
from pathlib import Path
path=Path('batches/glossary_batch_machine_learning_engineer/coverage_briefs.part.all.json')
a=json.loads(path.read_text()); before=json.loads(path.read_text())
b={x['concept_id']:x['evidence'] for x in a['briefs']}
def fact(cid,fid):return next(f for f in b['mle.'+cid]['required_facts'] if f['id']==fid)
def add(cid,fid,statement,refs):
 assert not any(f['id']==fid for f in b['mle.'+cid]['required_facts'])
 b['mle.'+cid]['required_facts'].append({'id':fid,'statement':statement,'source_refs':refs})
def move(cid,ids):
 e=b['mle.'+cid];e['optional_enrichment'].extend(f for f in e['required_facts'] if f['id'] in ids);e['required_facts']=[f for f in e['required_facts'] if f['id'] not in ids]
f=fact('numpy_shape_dtype','f1');f['statement']='Import NumPy with import numpy as np, which binds the module to the name np; create an array from the supplied list or tuple fixture with np.array(fixture) and inspect its ndim, shape and dtype.';f['source_refs'].append('numpy_user_guide#user/absolute_beginners.html — How to import NumPy')
f=fact('numpy_shape_dtype','f4');f['statement']='Use an if guard with a colon and an indented raise ValueError(message) to reject a violated input requirement; the indented rejection executes when the guard is true, rather than continuing with an invalid array.';f['source_refs'].append('python_tutorial#controlflow.html#if-statements — if Statements; #default-argument-values — ask_ok example with if retries < 0: raise ValueError')
add('numpy_shape_dtype','f6','Define a validator with def followed by its name, parenthesized parameters and a colon; put its body on following indented lines, and use return value to send the accepted result back to the caller.', ['python_tutorial#controlflow.html#defining-functions — Defining Functions'])
add('numpy_vectorization','f5','Construct an indexed reference output by allocating np.zeros(output_shape, dtype=declared_dtype), then using for i in range(input_array.shape[0]): with an indented assignment reference[i] = supplied_row_transform(input_array[i]); range stops before the row count, input_array[i] selects row i, and reference[i] assigns that row’s result before the allclose comparison.', ['python_tutorial#controlflow.html#for-statements — for Statements; #the-range-function — The range() Function', 'numpy_user_guide#user/absolute_beginners.html — How to create a basic array; Specifying your data type', 'numpy_user_guide#user/basics.indexing.html — Single element indexing; Assigning values to indexed arrays'])
add('numpy_vectorization','f6','A list-comprehension reference uses [expression for item in sequence], producing a new list by evaluating the expression for each item; convert the resulting reference list with np.array before comparing it with the array expression.', ['python_tutorial#datastructures.html#list-comprehensions — List Comprehensions', 'numpy_user_guide#user/absolute_beginners.html — How to create a basic array'])
add('dataset_inspection','f7','A parameter written name=default_value in a function signature is optional at the call site: the tutorial’s def parrot(voltage, state=\'a stiff\', action=\'voom\', type=\'Norwegian Blue\'): can be called as parrot(1000) using its defaults or as parrot(1000, action=\'VOOOOOM\') overriding action by keyword; use the same default-parameter and name=value call syntax for optional inspection settings.', ['python_tutorial#controlflow.html#default-argument-values — Default Argument Values', 'python_tutorial#controlflow.html#keyword-arguments — Keyword Arguments'])
add('pytorch_input_tensors','f3','Use A @ B or torch.matmul(A, B) for matrix multiplication: for two-dimensional inputs, (m, n) @ (n, p) produces (m, p), so check A.shape[1] == B.shape[0] before multiplication and the output shape afterwards; A * B instead multiplies elements under the elementwise broadcasting rules.', ['pytorch_learn_basics#tensorqs_tutorial.html — Operations on Tensors: Arithmetic operations', 'pytorch_learn_basics#https://docs.pytorch.org/docs/2.15/generated/torch.matmul.html — dimensionality rules; matrix-matrix examples'])
# Keep the restored f3 in its original numerical position.
e=b['mle.pytorch_input_tensors'];e['required_facts'].sort(key=lambda f:int(f['id'][1:]))
f=fact('task_loss_selection','f3');f['statement']='MSELoss takes input and target tensors of the same shape and, under mean reduction, sums squared elementwise differences and divides by M, the number of loss elements across all axes, not merely the number of examples.'
f=fact('task_loss_selection','f6');f['statement']='For unweighted mean binary cross-entropy with logits over M loss elements across all axes, mean reduction divides the sum of element losses by M and the logit derivative is (sigmoid(logit)−target)/M; this distinguishes the probability representation from the raw logit.'
f=fact('task_loss_selection','f7');f['statement']='For the unweighted mean class-index cross-entropy fixture with logits of shape (N, C), no ignored examples and no label smoothing, N is the number of examples: sum the per-example losses and divide by N, and compute each logit derivative as (softmax probability−one-hot target)/N.'
add('task_loss_selection','f8','Compute sigmoid(z) = 1 / (1 + exp(−z)), where exp is the exponential function, to convert each binary logit z to the probability used in the binary gradient reference.', ['pytorch_learn_basics#https://docs.pytorch.org/docs/2.15/generated/torch.nn.Sigmoid.html — Sigmoid formula'])
add('task_loss_selection','f9','For each row of C class logits, compute softmax probability p[c] = exp(z[c]) / sum_j exp(z[j]), summing over that row’s classes; torch.nn.Softmax(dim=1)(logits) performs this class-axis normalization for (N, C) logits.', ['pytorch_learn_basics#https://docs.pytorch.org/docs/2.15/generated/torch.nn.Softmax.html — Softmax formula; dim; Examples'])
add('task_loss_selection','f10','The one-hot target row has 1 at the target class index and 0 at each other class; torch.nn.functional.one_hot(targets, num_classes=C) converts long class-index targets of shape (N,) to these rows of shape (N, C) for the manual gradient reference.', ['pytorch_learn_basics#https://docs.pytorch.org/docs/2.15/generated/torch.nn.functional.one_hot.html — one_hot definition; Parameters'])
move('model_risk_documentation',{'f4'})
move('prediction_authentication',{'f6','f7','f8','f9'})
f=fact('model_preprocessing_package','f4');f['source_refs']=[('docker_docs#https://docs.docker.com/get-started/docker-concepts/building-images/build-tag-and-publish-an-image/ — Building images; Tagging images; Try it out: Build an image' if r.startswith('docker_docs#docker-concepts/building-images/build-tag-and-publish-an-image') else r) for r in f['source_refs']]
changed=[x['concept_id'] for x,y in zip(a['briefs'],before['briefs']) if x!=y]
assert set(changed)=={'mle.'+c for c in ['numpy_shape_dtype','numpy_vectorization','dataset_inspection','pytorch_input_tensors','task_loss_selection','model_risk_documentation','prediction_authentication','model_preprocessing_package']}
path.write_text(json.dumps(a,indent=2,ensure_ascii=False)+'\n')
print('Changed',len(changed),'briefs; total',len(a['briefs']))
print('Required facts',sum(len(x['evidence']['required_facts']) for x in a['briefs']),'optional',sum(len(x['evidence']['optional_enrichment']) for x in a['briefs']))
